<?php
declare(strict_types=1);
namespace App\Controller;
use App\Entity\PushSubscription; use App\Entity\User; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\Request; use Symfony\Component\HttpFoundation\Response; use Symfony\Component\Routing\Attribute\Route;
final class PushSubscriptionController extends AbstractController {
 #[Route('/api/push-subscription',name:'app_push_subscription',methods:['POST','DELETE'])] public function __invoke(Request $request,EntityManagerInterface $em):Response { $user=$this->getUser();if(!$user instanceof User||!$this->isCsrfTokenValid('push-subscription',$request->headers->get('X-CSRF-Token','')))throw $this->createAccessDeniedException();try{$data=json_decode($request->getContent(),true,512,JSON_THROW_ON_ERROR);$endpoint=$data['endpoint']??'';$key=$data['keys']['p256dh']??'';$auth=$data['keys']['auth']??'';if(!is_string($endpoint)||!filter_var($endpoint,FILTER_VALIDATE_URL))throw new \InvalidArgumentException();$subscription=$em->getRepository(PushSubscription::class)->findOneBy(['endpointHash'=>hash('sha256',$endpoint)]);if($request->isMethod('DELETE')){if($subscription instanceof PushSubscription&&$subscription->getUser()->getId()===$user->getId()){$em->remove($subscription);$em->flush();}return $this->json(['removed'=>true]);}if(!is_string($key)||!is_string($auth)||''===$key||''===$auth)throw new \InvalidArgumentException();$agent=$request->headers->get('User-Agent');if($subscription instanceof PushSubscription){if($subscription->getUser()->getId()!==$user->getId())return $this->json(['error'=>'Cet appareil appartient à un autre compte.'],409);$subscription->refresh($key,$auth,new \DateTimeImmutable(),$agent);}else{$subscription=PushSubscription::forUser($user,$endpoint,$key,$auth,new \DateTimeImmutable(),$agent);$em->persist($subscription);}$em->flush();return $this->json(['enabled'=>true]);}catch(\JsonException|\InvalidArgumentException){return $this->json(['error'=>'Abonnement invalide.'],422);} }
}
